{
  "directions": [
    {
      "id": "direcao-ciclo",
      "title": "O caminho dos potes",
      "concept": "Uma narrativa visual de ida e volta apresenta o acompanhamento como parte do percurso dos recipientes. Formas simples e textura de papel dão movimento à ideia.",
      "composition_plan": {
        "piece_id": "volta-pote-ciclo",
        "version": "1",
        "width_px": 1080,
        "height_px": 1080,
        "layers": [
          {"id":"c-fundo","kind":"shape","name":"Fundo pedra","shape":"rectangle","rect":{"x":0,"y":0,"width":1,"height":1},"fill_hex":"#ECE9DF","z_index":0},
          {"id":"c-imagem","kind":"image","name":"Percurso dos recipientes","asset_ref":"asset-ciclo-01","rect":{"x":0.06,"y":0.31,"width":0.88,"height":0.45},"z_index":1},
          {"id":"c-marca","kind":"text","name":"Nome","text":"VOLTA DE POTE","rect":{"x":0.07,"y":0.06,"width":0.86,"height":0.05},"font_ref":"arial","font_weight":700,"font_size_px":30,"color_hex":"#183F32","line_height":1.2,"text_align":"left","z_index":2},
          {"id":"c-titulo","kind":"text","name":"Chamada","text":"Seus potes vão.\nVocê acompanha.","rect":{"x":0.07,"y":0.13,"width":0.86,"height":0.15},"font_ref":"arial","font_weight":700,"font_size_px":64,"color_hex":"#183F32","line_height":1.1,"text_align":"left","z_index":3},
          {"id":"c-faixa","kind":"shape","name":"Faixa convite","shape":"rectangle","rect":{"x":0,"y":0.79,"width":1,"height":0.21},"fill_hex":"#183F32","z_index":4},
          {"id":"c-apoio","kind":"text","name":"Descrição","text":"Registre entregas, empréstimos e devoluções.","rect":{"x":0.07,"y":0.82,"width":0.86,"height":0.05},"font_ref":"arial","font_weight":400,"font_size_px":34,"color_hex":"#ECE9DF","line_height":1.2,"text_align":"left","z_index":5},
          {"id":"c-cta","kind":"text","name":"Convite","text":"Conheça a demonstração →","rect":{"x":0.07,"y":0.89,"width":0.86,"height":0.06},"font_ref":"arial","font_weight":700,"font_size_px":40,"color_hex":"#C9D94A","line_height":1.2,"text_align":"left","z_index":6}
        ]
      },
      "caption": "Seus recipientes fazem parte da rotina de entrega e retorno. Com a Volta de Pote, você registra entregas, empréstimos e devoluções e consulta quais ainda estão com clientes. Conheça a demonstração."
    },
    {
      "id": "direcao-bancada",
      "title": "A rotina de perto",
      "concept": "Uma cena tranquila de bancada aproxima a ferramenta do cotidiano de quem produz alimentos. A mensagem destaca a consulta dos recipientes que ainda estão com clientes, com uma linguagem editorial acolhedora.",
      "composition_plan": {
        "piece_id": "volta-pote-bancada",
        "version": "1",
        "width_px": 1080,
        "height_px": 1080,
        "layers": [
          {"id":"b-fundo","kind":"shape","name":"Fundo floresta","shape":"rectangle","rect":{"x":0,"y":0,"width":1,"height":1},"fill_hex":"#183F32","z_index":0},
          {"id":"b-painel","kind":"shape","name":"Painel pedra","shape":"rectangle","rect":{"x":0.04,"y":0.04,"width":0.92,"height":0.92},"fill_hex":"#ECE9DF","z_index":1},
          {"id":"b-marca","kind":"text","name":"Nome","text":"VOLTA DE POTE","rect":{"x":0.08,"y":0.08,"width":0.84,"height":0.05},"font_ref":"arial","font_weight":700,"font_size_px":30,"color_hex":"#183F32","line_height":1.2,"text_align":"left","z_index":2},
          {"id":"b-imagem","kind":"image","name":"Recipientes na bancada","asset_ref":"asset-bancada-01","rect":{"x":0.08,"y":0.14,"width":0.84,"height":0.37},"z_index":3},
          {"id":"b-titulo","kind":"text","name":"Chamada","text":"Um lugar para acompanhar\nseus recipientes.","rect":{"x":0.08,"y":0.54,"width":0.84,"height":0.13},"font_ref":"georgia","font_weight":700,"font_size_px":51,"color_hex":"#183F32","line_height":1.15,"text_align":"left","z_index":4},
          {"id":"b-apoio","kind":"text","name":"Descrição","text":"Veja quais ainda estão com clientes.","rect":{"x":0.08,"y":0.7,"width":0.84,"height":0.05},"font_ref":"arial","font_weight":400,"font_size_px":34,"color_hex":"#183F32","line_height":1.2,"text_align":"left","z_index":5},
          {"id":"b-destaque","kind":"shape","name":"Fundo convite","shape":"rectangle","rect":{"x":0.08,"y":0.79,"width":0.65,"height":0.1},"fill_hex":"#C9D94A","z_index":6},
          {"id":"b-cta","kind":"text","name":"Convite","text":"Conheça a demonstração →","rect":{"x":0.1,"y":0.82,"width":0.61,"height":0.05},"font_ref":"arial","font_weight":700,"font_size_px":36,"color_hex":"#183F32","line_height":1.2,"text_align":"left","z_index":7}
        ]
      },
      "caption": "Na rotina de quem produz alimentos, cada recipiente tem seu caminho. A Volta de Pote reúne o registro de entregas, empréstimos e devoluções e ajuda você a consultar quais ainda estão com clientes. Conheça a demonstração."
    }
  ],
  "asset_requests": [
    {
      "direction_id": "direcao-ciclo",
      "asset_ref": "asset-ciclo-01",
      "prompt": "Ilustração horizontal de recipientes retornáveis percorrendo um caminho de ida e volta entre uma pequena produção de alimentos e seus clientes, usando formas simples e textura fosca de papel. Paleta floresta #183F32, lima #C9D94A e pedra #ECE9DF. Imagem sem letras, palavras, números, logotipos ou marcas-d'água; sem telas ou interfaces."
    },
    {
      "direction_id": "direcao-bancada",
      "asset_ref": "asset-bancada-01",
      "prompt": "Cena horizontal editorial de uma bancada de pequeno produtor de alimentos com recipientes retornáveis de vidro, composição calma e próxima, superfícies foscas e textura sutil de papel. Paleta floresta #183F32, lima #C9D94A e pedra #ECE9DF. Imagem sem letras, palavras, números, rótulos, logotipos ou marcas-d'água; sem telas ou interfaces."
    }
  ],
  "conversation_response": "A primeira direção conta o percurso dos recipientes; a segunda aproxima o produto da rotina na bancada. Os IDs dos ativos são reservas para geração futura. Os planos foram preparados, mas ainda não foram renderizados; a composição deverá confirmar o encaixe dos textos e dos ativos. Você pode escolher, ajustar ou rejeitar ambas."
}

